export function UserCard({user}:{user:User}){
  const [loaded, setLoaded] = useState(false)
  return (
    <div className="rounded-xl border p-4">
      {!loaded && <div className="h-12 w-12 animate-pulse rounded-full bg-muted" />}
      <img src={user.avatarUrl} alt={user.name} onLoad={() => setLoaded(true)} className={loaded ? "h-12 w-12 rounded-full" : "hidden"} />
